mapper.select:
SELECT id,dept_name AS deptName,`tel`,`email`,`desc`
FROM dept
WHERE id = #{id}

SELECT d.id,d.dept_name AS deptName,d.tel,d.email,d.desc,COUNT(u.id) AS emps FROM dept d LEFT JOIN users u ON u.dept_id=d.id AND u.status=1 WHERE 1=1
AND d.dept_name LIKE '%${deptName}%'
GROUP BY d.id LIMIT #{start}, #{length}

SELECT IF( SUM( temp.users ) > 0, FALSE, TRUE ) AS result FROM ( SELECT COUNT( u.id ) AS users FROM dept d JOIN users u ON d.id=u.dept_id WHERE d.id IN
#{one}
GROUP BY d.id ) temp

mapper.update:
UPDATE dept
SET dept_name=#{deptName},
    tel=#{tel},
    email=#{email},
    `desc`=#{desc}
WHERE id=#{id}

